  "Resting heart rate (74 BPM) and HRV (68 ms) indicate excellent cardiovascular conditioning and recovery.": {
    en: "Resting heart rate (74 BPM) and HRV (68 ms) indicate excellent cardiovascular conditioning and recovery.",
    hi: "विश्राम हृदय गति (74 BPM) और HRV (68 ms) उत्कृष्ट हृदय स्वास्थ्य और रिकवरी दर्शाते हैं।",
    bn: "বিশ্রামের হৃদস্পন্দন (৭৪ BPM) এবং HRV (৬৮ ms) চমৎকার কার্ডিওভাসকুলার স্বাস্থ্য নির্দেশ করে।",
    ta: "ஓய்வு இதயத் துடிப்பு (74 BPM) மற்றும் HRV (68 ms) சிறந்த இருதய ஆரோக்கியத்தைக் குறிக்கிறது.",
    te: "విశ్రాంతి హృదయ స్పందన రేటు (74 BPM) మరియు HRV (68 ms) అద్భుతమైన కార్డియోవాస్కులర్ రికవరీని సూచిస్తాయి.",
    mr: "विश्रांती हृदय गती (७४ BPM) आणि HRV (६८ ms) उत्तम हृदय कार्यक्षमता दर्शवतात.",
    gu: "વિશ્રામ હૃદય દર (૭૪ BPM) અને HRV (૬૮ ms) ઉત્તમ કાર્ડિયોવેસ્ક્યુલર સ્વાસ્થ્ય દર્શાવે છે.",
    kn: "ವಿಶ್ರಾಂತಿ ಹೃದಯ ಬಡಿತ (74 BPM) ಮತ್ತು HRV (68 ms) ಅತ್ಯುತ್ತಮ ಹೃದಯ ಕಂಡೀಷನಿಂಗ್ ಅನ್ನು ಸೂಚಿಸುತ್ತವೆ.",
    ml: "വിശ്രമവേളയിലെ ഹൃദയമിടിപ്പ് (74 BPM), HRV (68 ms) മികച്ച ഹൃദയാരോഗ്യത്തെ സൂചിപ്പിക്കുന്നു.",
    pa: "ਆਰਾਮ ਦਿਲ ਦੀ ਧੜਕਣ (74 BPM) ਅਤੇ HRV (68 ms) ਵਧੀਆ ਦਿਲ ਦੀ ਸਿਹਤ ਨੂੰ ਦਰਸਾਉਂਦੇ ਹਨ।",
    or: "ବିଶ୍ରାମ ହୃଦସ୍ପନ୍ଦନ (୭୪ BPM) ଏବଂ HRV (୬୮ ms) ଉତ୍କୃଷ୍ଟ ହୃଦୟ ସ୍ୱାସ୍ଥ୍ୟ ଦର୍ଶାଏ ।"
  },
