  "Daily hydration goal at 82%. Target 500ml additional water intake during afternoon focus hours.": {
    en: "Daily hydration goal at 82%. Target 500ml additional water intake during afternoon focus hours.",
    hi: "दैनिक जलयोजन लक्ष्य 82% पर है। दोपहर के समय 500 मिली अतिरिक्त पानी पीने का लक्ष्य रखें।",
    bn: "দৈনিক হাইড্রেশন লক্ষ্য ৮২%। বিকেলে অতিরিক্ত ৫০০ মিলি জল পান করার লক্ষ্য রাখুন।",
    ta: "தினசரி நீரேற்ற இலக்கு 82%. பிற்பகலில் கூடுதலாக 500 மிலி தண்ணீர் குடிக்கவும்.",
    te: "రోజువారీ హైడ్రేషన్ లక్ష్యం 82% వద్ద ఉంది. మధ్యాహ్నం 500ml అదనపు నీటిని తీసుకోండి.",
    mr: "दैनिक हायड्रेशन उद्दिष्ट ८२% वर आहे. दुपारी ५०० मिली अतिरिक्त पाणी पिण्याचे लक्ष्य ठेवा.",
    gu: "દૈનિક હાઇડ્રેશન લક્ષ્ય ૮૨% પર છે. બપોરે વધારાનું ૫૦૦ મિલી પાણી પીઓ.",
    kn: "ದೈನಂದಿನ ಹೈಡ್ರೇಶನ್ ಗುರಿ 82%. ಮಧ್ಯಾಹ್ನ ಹೆಚ್ಚುವರಿ 500 ಮಿಲಿ ನೀರು ಕುಡಿಯಿರಿ.",
    ml: "പ്രതിദിന ജലാംശ ലക്ഷ്യം 82%. ഉച്ചതിരിഞ്ഞ് 500 മില്ലി അധിക വെള്ളം കുടിക്കുക.",
    pa: "ਰੋਜ਼ਾਨਾ ਪਾਣੀ ਪੀਣ ਦਾ ਟੀਚਾ 82% ਹੈ। ਦੁਪਹਿਰ ਵੇਲੇ 500ml ਹੋਰ ਪਾਣੀ ਪੀਓ।",
    or: "ଦୈନିକ ଜଳୀୟ ଲକ୍ଷ୍ୟ ୮୨% ଅଛି । ଅପରାହ୍ନରେ ଅତିରିକ୍ତ ୫୦୦ ମିଲି ପାଣି ପିଅନ୍ତୁ ।"
  },
