  "Continue desk stretches every 90 minutes to maintain optimal cervical spinal alignment.": {
    en: "Continue desk stretches every 90 minutes to maintain optimal cervical spinal alignment.",
    hi: "गर्दन और रीढ़ की हड्डी के संरेखण को बनाए रखने के लिए हर 90 मिनट में स्ट्रेचिंग जारी रखें।",
    bn: "ঘাড় ও মেরুদণ্ডের সুরক্ষার জন্য প্রতি ৯০ মিনিটে হালকা স্ট্রেচিং চালিয়ে যান।",
    ta: "கழுத்து மற்றும் முதுகெலும்பு சீரமைப்பைப் பராமரிக்க ஒவ்வொரு 90 நிமிடங்களுக்கும் நீட்சிப் பயிற்சிகளைத் தொடரவும்.",
    te: "వెన్నెముక అమరికను కాపాడుకోవడానికి ప్రతి 90 నిమిషాలకు స్ట్రెచింగ్ వ్యాయామాలు చేయండి.",
    mr: "मानेच्या मणक्याचे योग्य संरेखन राखण्यासाठी दर ९० मिनिटांनी स्ट्रेचिंग करा.",
    gu: "ડોક અને કરોડરજ્જુના સ્વાસ્થ્ય માટે દર ૯૦ મિનિટે સ્ટ્રેચિંગ કરો.",
    kn: "ಕುತ್ತಿಗೆ ಮತ್ತು ಬೆನ್ನುಮೂಳೆಯ ಆರೋಗ್ಯವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಲು ಪ್ರತಿ 90 ನಿಮಿಷಗಳಿಗೊಮ್ಮೆ ಸ್ಟ್ರೆಚಿಂಗ್ ಮುಂದುವರಿಸಿ.",
    ml: "കഴുത്തിന്റെയും നട്ടെല്ലിന്റെയും ആരോഗ്യത്തിനായി ഓരോ 90 മിനിറ്റിലും സ്ട്രെച്ചിംഗ് വ്യായാമങ്ങൾ ചെയ്യുക.",
    pa: "ਧੌਣ ਅਤੇ ਰੀੜ੍ਹ ਦੀ ਹੱਡੀ ਦੀ ਸਿਹਤ ਲਈ ਹਰ 90 ਮਿੰਟ ਬਾਅਦ ਹਲਕੀ ਕਸਰਤ ਕਰੋ।",
    or: "ବେକ ଏବଂ ମେରୁଦଣ୍ଡ ସୁରକ୍ଷା ପାଇଁ ପ୍ରତି ୯୦ ମିନିଟରେ ଷ୍ଟ୍ରେଚିଂ ଜାରି ରଖନ୍ତୁ ।"
  },
