  "O2 Saturation: 98.5%, FEV1: 4.8L. Clear bilateral breath sounds with normal alveolar diffusion.": {
    en: "O2 Saturation: 98.5%, FEV1: 4.8L. Clear bilateral breath sounds with normal alveolar diffusion.",
    hi: "ऑक्सीजन संतृप्ति: 98.5%, FEV1: 4.8L। सामान्य वायुकोशीय विसरण के साथ दोनों फेफड़ों की सांस की आवाजें स्पष्ट।",
    bn: "অক্সিজেন স্যাচুরেশন: ৯৮.৫%, FEV1: ৪.৮L। উভয় ফুসফুসে স্বাভাবিক অ্যালভিওলার প্রসারণসহ পরিষ্কার শ্বাস-শব্দ।",
    ta: "ஆக்சிஜன் அளவு: 98.5%, FEV1: 4.8L. இயல்பான காற்றுப் பரிமாற்றத்துடன் இருபுறமும் தெளிவான சுவாச ஒலிகள்.",
    te: "ఆక్సిజన్ సంతృప్తత: 98.5%, FEV1: 4.8L. సాధారణ అల్వియోలార్ వ్యాప్తితో స్పష్టమైన ద్వైపాక్షిక శ్వాస శబ్దాలు.",
    mr: "ऑक्सिजन संपृक्तता: ९८.५%, FEV1: ४.८L. सामान्य वायुकोशीय विसरणासह दोन्ही बाजूंनी स्पष्ट श्वासोच्छ्वास आवाज.",
    gu: "ઓક્સિજન સેચ્યુરેશન: ૯૮.૫%, FEV1: ૪.૮L. સામાન્ય એલ્વિઓલર પ્રસરણ સાથે બંને ફેફસાંમાં સ્પષ્ટ શ્વાસનો અવાજ.",
    kn: "ಆಕ್ಸಿಜನ್ ಸ್ಯಾಚುರೇಶನ್: 98.5%, FEV1: 4.8L. ಸಾಮಾನ್ಯ ಅಲ್ವಿಯೋಲಾರ್ ಪ್ರಸರಣದೊಂದಿಗೆ ಸ್ಪಷ್ಟ ಉಸಿರಾಟದ ಶಬ್ದಗಳು.",
    ml: "ഓക്സിജൻ സാച്ചുറേഷൻ: 98.5%, FEV1: 4.8L. സാധാരണ ശ്വാസകോശ വ്യാപനത്തോടെയുള്ള വ്യക്തമായ ശ്വസന ശബ്ദങ്ങൾ.",
    pa: "ਆਕਸੀਜਨ ਸੰਤ੍ਰਿਪਤਾ: 98.5%, FEV1: 4.8L। ਦੋਵੇਂ ਫੇਫੜਿਆਂ ਵਿੱਚ ਸਾਫ਼ ਸਾਹ ਦੀਆਂ ਆਵਾਜ਼ਾਂ।",
    or: "ଅମ୍ଳଜାନ ସାନ୍ଦ୍ରତା: ୯୮.୫%, FEV1: ୪.୮L। ସାଧାରଣ ଶ୍ୱାସକ୍ରିୟା ଶବ୍ଦ ସହିତ ଉଭୟ ଫୁସଫୁସ୍ ସ୍ପଷ୍ଟ।"
  },
