  "Mild trapezius stiffness from display work. Ergonomic desk setup and scapular stretches recommended.": {
    en: "Mild trapezius stiffness from display work. Ergonomic desk setup and scapular stretches recommended.",
    hi: "स्क्रीन कार्य से कंधे में हल्का खिंचाव। एर्गोनोमिक डेस्क व्यवस्था और स्कैपुलर स्ट्रेचिंग की सलाह।",
    bn: "স্ক্রিন ব্যবহারের কারণে কাঁধে হালকা শক্তভাব। এর্গোনোমিক ডেস্ক সেটআপ এবং স্ট্রেচিংয়ের পরামর্শ।",
    ta: "திரை வேலையால் தோள்பட்டையில் லேசான இறுக்கம். எர்கோனாமிக் டெஸ்க் மற்றும் ஸ்ட்ரெட்ச் பயிற்சிகள் பரிந்துரைக்கப்படுகின்றன.",
    te: "స్క్రీన్ పని వలన భుజాలలో తేలికపాటి బిగుతు. ఎర్గోనామిక్ డెస్క్ సెటప్ మరియు స్ట్రెచింగ్ సిఫార్సు చేయబడింది.",
    mr: "स्क्रीनवरील कामामुळे खांद्यात सौम्य ताण. एर्गोनॉमिक डेस्क सेटअप आणि स्ट्रेचिंगची शिफारस.",
    gu: "સ્ક્રીન વર્કને કારણે ખભામાં હળવી જડતા. એર્ગોનોમિક ડેસ્ક સેટઅપ અને સ્ટ્રેચિંગની ભલામણ.",
    kn: "ಸ್ಕ್ರೀನ್ ಕೆಲಸದಿಂದ ಭುಜಗಳಲ್ಲಿ ಸೌಮ್ಯ ಬಿಗಿತ. ಎರ್ಗೊನಾಮಿಕ್ ಡೆಸ್ಕ್ ಸೆಟಪ್ ಮತ್ತು ಸ್ಟ್ರೆಚಿಂಗ್ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ.",
    ml: "സ്ക്രീൻ ഉപയോഗം കാരണം തോളിൽ നേരിയ കാഠിന്യം. എർഗണോമിക് ഡെസ്കും വ്യായാമങ്ങളും നിർദ്ദേശിക്കുന്നു.",
    pa: "ਸਕ੍ਰੀਨ ਦੇ ਕੰਮ ਕਾਰਨ ਮੋਢੇ ਵਿੱਚ ਹਲਕੀ ਅਕੜਾਅ। ਐਰਗੋਨੋਮਿਕ ਡੈਸਕ ਸੈੱਟਅੱਪ ਅਤੇ ਸਟ੍ਰੈਚਿੰਗ ਦੀ ਸਿਫਾਰਸ਼।",
    or: "ସ୍କ୍ରିନ୍ କାର୍ଯ୍ୟ ଯୋଗୁଁ କାନ୍ଧରେ ସାମାନ୍ୟ କଠିନତା। ଏର୍ଗୋନୋମିକ୍ ଡେସ୍କ ଏବଂ ଷ୍ଟ୍ରେଚିଂ ପରାମର୍ଶିତ।"
  },
