  "Healthy joint space. Full physiological range of motion with preserved articular cartilage.": {
    en: "Healthy joint space. Full physiological range of motion with preserved articular cartilage.",
    hi: "स्वस्थ जोड़ स्थान। सुरक्षित आर्टिकुलर उपास्थि के साथ गति की पूर्ण शारीरिक सीमा।",
    bn: "স্বাস্থ্যকর জয়েন্ট স্পেস। সংরক্ষিত তরুণাস্থিসহ চলাচলের সম্পূর্ণ স্বাভাবিক পরিসীমা।",
    ta: "ஆரோக்கியமான மூட்டு இடைவெளி. குருத்தெலும்புடன் கூடிய முழுமையான அசைவு வரம்பு.",
    te: "ఆరోగ్యకరమైన ఉమ్మడి స్థలం. మృదులాస్థితో పూర్తి స్థాయి కదలిక.",
    mr: "निरोगी सांधे जागा. संरक्षित उपास्थिसह पूर्ण हालचालींची श्रेणी.",
    gu: "સ્વસ્થ સાંધાની જગ્યા. અખંડ કાસ્થિ સાથે સંપૂર્ણ ગતિશીલતા.",
    kn: "ಆರೋಗ್ಯಕರ ಕೀಲು ಜಾಗ. ಸಂರಕ್ಷಿತ ಕಾರ್ಟಿಲೆಜ್‌ನೊಂದಿಗೆ ಪೂರ್ಣ ಚಲನೆಯ ಶ್ರೇಣಿ.",
    ml: "ആരോഗ്യമുള്ള സന്ധി ഇടം. തരുണാസ്ഥിയോടു കൂടിയ പൂർണ്ണ ചലന ശേഷി.",
    pa: "ਸਿਹਤਮੰਦ ਜੋੜਾਂ ਦੀ ਥਾਂ। ਸੁਰੱਖਿਅਤ ਉਪਾਸਥੀ ਦੇ ਨਾਲ ਪੂਰੀ ਗਤੀ ਦੀ ਸੀਮਾ।",
    or: "ସ୍ୱାସ୍ଥ୍ୟକର ଗଣ୍ଠି ସ୍ଥାନ। ସୁରକ୍ଷିତ ଉପାସ୍ଥି ସହିତ ସମ୍ପୂର୍ଣ୍ଣ ଗତିଶୀଳତା।"
  },
