  "Automated early warning triggers for localized dengue, cholera, nipah, and zika cluster outbreaks.": {
    en: "Automated early warning triggers for localized dengue, cholera, nipah, and zika cluster outbreaks.",
    hi: "डेंगू, हैजा, निपाह और जीका प्रकोपों के लिए स्वचालित पूर्व चेतावनी अलर्ट।",
    bn: "ডেঙ্গু, কলেরা, নিপাহ এবং জিকা প্রাদুর্ভাবের জন্য স্বয়ংক্রিয় পূর্ব সতর্কতা সংকেত।",
    ta: "டெங்கு, காலரா, நிபா மற்றும் ஜிகா நோய் பரவலுக்கான தானியங்கி முன் எச்சரிக்கைகள்.",
    te: "డెంగ్యూ, కలరా, నిపా మరియు జికా వ్యాప్తికి ముందస్తు హెచ్చరికలు.",
    mr: "डेंग्यू, कॉलरा, निपाह आणि झिका उद्रेकांसाठी स्वयंचलित पूर्वसूचना.",
    gu: "ડેન્ગ્યુ, કોલેરા, નિપાહ અને ઝિકા પ્રકોપ માટે સ્વચાલિત પૂર્વ ચેતવણી ટ્રિગર્સ.",
    kn: "ಡೆಂಗ್ಯೂ, ಕಾಲರಾ, ನಿಪಾ ಮತ್ತು ಝಿಕಾ ಹರಡುವಿಕೆಗೆ ಸ್ವಯಂಚಾಲಿತ ಮುನ್ನೆಚ್ಚರಿಕೆಗಳು.",
    ml: "ഡെങ്കിപ്പനി, കോളറ, നിപ്പ, സിക എന്നിവയുടെ വ്യാപനത്തിനുള്ള മുൻകൂർ മുന്നറിയിപ്പുകൾ.",
    pa: "ਡੇਂਗੂ, ਹੈਜ਼ਾ, ਨਿਪਾਹ ਅਤੇ ਜ਼ੀਕਾ ਫੈਲਣ ਲਈ ਆਟੋਮੈਟਿਕ ਅਗਾਊਂ ਚੇਤਾਵਨੀ।",
    or: "ଡେଙ୍ଗୁ, କଲେରା, ନିପା ଏବଂ ଜିକା ରୋଗ ପାଇଁ ସ୍ୱୟଂଚାଳିତ ପୂର୍ବ ଚେତାବନୀ।"
  },
