  "₹5 Lakh secondary/tertiary hospital cashless coverage + 80% discounted generic medicines.": {
    en: "₹5 Lakh secondary/tertiary hospital cashless coverage + 80% discounted generic medicines.",
    hi: "₹5 लाख तक कैशलेस अस्पताल कवरेज + 80% तक सस्ती जेनेरिक दवाएं।",
    bn: "₹৫ লাখ পর্যন্ত ক্যাশলেস হাসপাতাল কভারেজ + ৮০% পর্যন্ত সাশ্রয়ী জেনেরিক ওষুধ।",
    ta: "₹5 லட்சம் வரை கட்டணமில்லா மருத்துவமனை சிகிச்சை + 80% வரை மலிவான ஜெனரிக் மருந்துகள்.",
    te: "₹5 లక్షల వరకు నగదు రహిత ఆసుపత్రి కవరేజ్ + 80% వరకు రాయితీతో కూడిన జనరిక్ మందులు.",
    mr: "₹५ लाखांपर्यंत कॅशलेस हॉस्पिटल संरक्षण + ८०% पर्यंत स्वस्त जेनेरिक औषधे.",
    gu: "₹૫ લાખ સુધી કેશલેસ હોસ્પિટલ કવરેજ + ૮૦% સુધી સસ્તી જેનરિક દવાઓ.",
    kn: "₹5 ಲಕ್ಷದವರೆಗೆ ನಗದು ರಹಿತ ಆಸ್ಪತ್ರೆ ಸೌಲಭ್ಯ + 80% ವರೆಗೆ ರಿಯಾಯಿತಿ ದರದ ಜೆನೆರಿಕ್ ಔಷಧಗಳು.",
    ml: "₹5 ലക്ഷം രൂപ വരെ സൗജന്യ ആശുപത്രി ചികിത്സ + 80% വിലക്കുറവിൽ ജനറിക് മരുന്നുകൾ.",
    pa: "₹5 ਲੱਖ ਤੱਕ ਕੈਸ਼ਲੈੱਸ ਹਸਪਤਾਲ ਕਵਰੇਜ + 80% ਤੱਕ ਸਸਤੀਆਂ ਜੈਨੇਰਿਕ ਦਵਾਈਆਂ।",
    or: "₹୫ ଲକ୍ଷ ପର୍ଯ୍ୟନ୍ତ କ୍ୟାଶଲେସ୍ ଚିକିତ୍ସା ସୁବିଧା + ୮୦% ଶସ୍ତା ଜେନେରିକ୍ ଔଷଧ।"
  },
