  "Select from 6 standardized clinical patient mock JSON datasets, or upload your personal Apple Health export.xml / Google Takeout JSON.": {
    en: "Select from 6 standardized clinical patient mock JSON datasets, or upload your personal Apple Health export.xml / Google Takeout JSON.",
    hi: "6 मानकीकृत क्लिनिकल मरीज़ डेटासेट में से चुनें, या अपनी व्यक्तिगत Apple Health export.xml / Google Takeout JSON फ़ाइल अपलोड करें।",
    bn: "৬টি প্রমিত ক্লিনিকাল রোগীর ডেটাসেট থেকে নির্বাচন করুন, অথবা ব্যক্তিগত Apple Health export.xml / Google Takeout আপলোড করুন।",
    ta: "6 தரப்படுத்தப்பட்ட மருத்துவ நோயாளி தரவுத்தொகுப்புகளிலிருந்து தேர்ந்தெடுக்கவும் அல்லது உங்கள் தனிப்பட்ட கோப்பைப் பதிவேற்றவும்.",
    te: "6 ప్రామాణిక క్లినికల్ పేషెంట్ డేటాసెట్‌ల నుండి ఎంచుకోండి లేదా మీ వ్యక్తిగత ఫైల్‌ను అప్‌లోడ్ చేయండి.",
    mr: "६ प्रमाणित वैद्यकीय रुग्ण डेटासेटमधून निवडा किंवा तुमची वैयक्तिक Apple Health / Google Takeout फाइल अपलोड करा.",
    gu: "૬ પ્રમાણભૂત ક્લિનિકલ દર્દી ડેટાસેટ્સમાંથી પસંદ કરો, અથવા તમારી વ્યક્તિગત ફાઇલ અપલોડ કરો.",
    kn: "6 ಪ್ರಮಾಣಿತ ವೈದ್ಯಕೀಯ ರೋಗಿಯ ಡೇಟಾಸೆಟ್‌ಗಳಿಂದ ಆಯ್ಕೆಮಾಡಿ ಅಥವಾ ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಫೈಲ್ ಅನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ.",
    ml: "6 ക്ലിനിക്കൽ ഡാറ്റാസെറ്റുകളിൽ നിന്ന് തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ നിങ്ങളുടെ സ്വകാര്യ ഫയൽ അപ്‌ലോഡ് ചെയ്യുക.",
    pa: "6 ਮਿਆਰੀ ਕਲੀਨਿਕਲ ਮਰੀਜ਼ ਡਾਟਾਸੈਟਾਂ ਵਿੱਚੋਂ ਚੁਣੋ, ਜਾਂ ਆਪਣੀ ਨਿੱਜੀ ਫਾਈਲ ਅੱਪਲੋਡ ਕਰੋ।",
    or: "୬ଟି ମାନକ କ୍ଲିନିକାଲ୍ ରୋଗୀ ଡାଟାସେଟ୍‌ରୁ ଚୟନ କରନ୍ତୁ କିମ୍ବା ବ୍ୟକ୍ତିଗତ ଫାଇଲ୍ ଅପଲୋଡ୍ କରନ୍ତୁ।"
  },
